execution_contexts => {"type": "array", "items": {"type": "object", "additionalProperties": false, "required": ["worktree_id", "branch", "base_branch", "head_sha", "state", "lease_acquired_at", "last_seen_at", "released_at"], "properties": {"worktree_id": {"type": "string", "patter
completion_evidence => {"type": "object", "additionalProperties": false, "required": ["policy", "status", "source", "completed_at", "reconciled_at", "evidence_refs"], "properties": {"policy": {"type": "string", "enum": ["manual", "linked_pr_merged_all", "linked_pr_merged_any", "issu
implementation_readiness => {"type": "object", "required": ["status", "missing_sections", "checked_at"], "properties": {"status": {"type": "string", "enum": ["complete", "incomplete", "not_applicable"]}, "missing_sections": {"type": "array", "items": {"type": "string"}, "uniqueItems": tr
