[
 {
  "if": {
   "properties": {
    "artifact_kind": {
     "const": "architecture"
    }
   }
  },
  "then": {
   "properties": {
    "artifact_subtypes": {
     "minItems": 1,
     "items": {
      "enum": [
       "frontend",
       "backend",
       "infrastructure",
       "data",
       "security"
      ]
     }
    }
   }
  }
 },
 {
  "if": {
   "properties": {
    "artifact_kind": {
     "const": "specification"
    }
   }
  },
  "then": {
   "properties": {
    "artifact_subtypes": {
     "items": {
      "enum": [
       "api",
       "frontend",
       "backend",
       "infrastructure",
       "data",
       "security"
      ]
     }
    }
   }
  }
 },
 {
  "if": {
   "properties": {
    "artifact_kind": {
     "enum": [
      "issue",
      "task",
      "document",
      "feature"
     ]
    }
   }
  },
  "then": {
   "properties": {
    "artifact_subtypes": {
     "maxItems": 0
    }
   }
  }
 },
 {
  "if": {
   "properties": {
    "artifact_kind": {
     "const": "feature"
    }
   }
  },
  "then": {
   "properties": {
    "purpose": {
     "type": "string",
     "minLength": 1
    },
    "goal": {
     "type": "string",
     "minLength": 1
    },
    "scope_in": {
     "minItems": 1
    },
    "scope_out": {
     "minItems": 1
    },
    "acceptance": {
     "minItems": 1
    },
    "architecture_refs": {
     "minItems": 1
    }
   },
   "required": [
    "purpose",
    "goal",
    "scope_in",
    "scope_out",
    "acceptance",
    "architecture_refs"
   ]
  }
 },
 {
  "if": {
   "properties": {
    "artifact_kind": {
     "enum": [
      "issue",
      "specification",
      "architecture",
      "document",
      "feature"
     ]
    }
   }
  },
  "then": {
   "properties": {
    "parent_feature": {
     "const": null
    },
    "feature_package_id": {
     "const": null
    },
    "phase_ref": {
     "const": null
    }
   }
  }
 },
 {
  "if": {
   "required": [
    "artifact_kind",
    "parent_feature"
   ],
   "properties": {
    "artifact_kind": {
     "const": "task"
    },
    "parent_feature": {
     "type": "string"
    }
   }
  },
  "then": {
   "properties": {
    "feature_package_id": {
     "type": "string"
    },
    "phase_ref": {
     "type": "string",
     "pattern": "^P(0[1-9]|1[0-3])$"
    }
   }
  }
 },
 {
  "if": {
   "required": [
    "artifact_kind",
    "parent_feature"
   ],
   "properties": {
    "artifact_kind": {
     "const": "task"
    },
    "parent_feature": {
     "const": null
    }
   }
  },
  "then": {
   "properties": {
    "feature_package_id": {
     "const": null
    },
    "phase_ref": {
     "const": null
    }
   }
  }
 },
 {
  "if": {
   "properties": {
    "evaluation_status": {
     "const": "pass"
    }
   }
  },
  "then": {
   "properties": {
    "confirmation_status": {
     "const": "confirmed"
    },
    "confirmation_evidence": {
     "properties": {
      "evaluator": {
       "type": "string",
       "minLength": 1
      },
      "evidence_ref": {
       "type": "string",
       "minLength": 1
      },
      "evaluated_digest": {
       "type": "string",
       "pattern": "^[a-f0-9]{64}$"
      }
     }
    },
    "implementation_readiness": {
     "properties": {
      "status": {
       "const": "complete"
      },
      "missing_sections": {
       "maxItems": 0
      },
      "checked_at": {
       "type": "string",
       "format": "date-time"
      }
     }
    }
   }
  }
 },
 {
  "if": {
   "properties": {
    "status": {
     "const": "active"
    }
   }
  },
  "then": {
   "properties": {
    "confirmation_status": {
     "const": "confirmed"
    },
    "evaluation_status": {
     "const": "pass"
    },
    "implementation_readiness": {
     "properties": {
      "status": {
       "const": "complete"
      }
     }
    }
   }
  }
 },
 {
  "if": {
   "properties": {
    "github_publication": {
     "properties": {
      "mode": {
       "enum": [
        "issue",
        "issue_and_projects"
       ]
      }
     }
    }
   }
  },
  "then": {
   "properties": {
    "artifact_kind": {
     "enum": [
      "issue",
      "task"
     ]
    },
    "confirmation_status": {
     "const": "confirmed"
    },
    "evaluation_status": {
     "const": "pass"
    },
    "implementation_readiness": {
     "properties": {
      "status": {
       "const": "complete"
      }
     }
    }
   }
  }
 },
 {
  "if": {
   "properties": {
    "completion_evidence": {
     "properties": {
      "status": {
       "const": "done"
      },
      "policy": {
       "const": "linked_pr_merged_all"
      }
     }
    }
   }
  },
  "then": {
   "properties": {
    "status": {
     "const": "done"
    },
    "pull_request_linkages": {
     "minItems": 1,
     "items": {
      "properties": {
       "state": {
        "const": "merged"
       }
      }
     }
    },
    "completion_evidence": {
     "properties": {
      "completed_at": {
       "type": "string",
       "format": "date-time"
      },
      "reconciled_at": {
       "type": "string",
       "format": "date-time"
      },
      "source": {
       "const": "github_pr_merge"
      },
      "evidence_refs": {
       "minItems": 1
      }
     }
    }
   }
  }
 },
 {
  "if": {
   "properties": {
    "completion_evidence": {
     "properties": {
      "status": {
       "const": "done"
      },
      "policy": {
       "const": "linked_pr_merged_any"
      }
     }
    }
   }
  },
  "then": {
   "properties": {
    "status": {
     "const": "done"
    },
    "pull_request_linkages": {
     "minItems": 1,
     "contains": {
      "properties": {
       "state": {
        "const": "merged"
       }
      }
     }
    },
    "completion_evidence": {
     "properties": {
      "completed_at": {
       "type": "string",
       "format": "date-time"
      },
      "reconciled_at": {
       "type": "string",
       "format": "date-time"
      },
      "source": {
       "const": "github_pr_merge"
      },
      "evidence_refs": {
       "minItems": 1
      }
     }
    }
   }
  }
 }

